# Reconstruct both demonstration grids from their repeated patterns and marked separator intersections.
# Demo 1
h,w=24,23
D1=[]
for r in range(h):
    if r in (1,6,11,16,21):
        row=[9]*w
    else:
        row=[9 if c%3==2 else 8 for c in range(w)]
    D1.append(row)
for r, marks in {
    6:{2:3,5:3,8:2,11:2},
    11:{2:3,5:3,8:2,11:2,14:2,17:5,20:5},
    16:{2:3,5:3,11:2,14:2,17:5,20:5},
}.items():
    for c,v in marks.items(): D1[r][c]=v

# Demo 2
h,w=30,29
D2=[]
for r in range(h):
    if r in (4,10,16,22,28): row=[6]*w
    else: row=[6 if c in (4,12,20,28) else 7 for c in range(w)]
    D2.append(row)
for r, marks in {
    4:{4:4,12:4,20:4}, 10:{4:4,12:4,20:4},
    22:{4:8,12:8,20:2,28:2}, 28:{4:8,12:8,20:2,28:2}
}.items():
    for c,v in marks.items(): D2[r][c]=v

print(transform(D1))
print(transform(D2))
